COMMENT ON TABLE public.bank_accounts IS 'Contas bancárias por loja (banco, agência, conta, saldo inicial/atual) para conciliação financeira.';
COMMENT ON TABLE public.bank_transactions IS 'Transações bancárias (extrato), em geral importadas de OFX. Marcadas como conciliadas ao casar com lançamentos.';
COMMENT ON TABLE public.ofx_imports IS 'Importações de arquivos OFX de extrato bancário (período, contagem, totais de crédito/débito).';
COMMENT ON TABLE public.credit_cards IS 'Cartões de crédito por loja (bandeira, limite, dias de fechamento/vencimento).';
COMMENT ON TABLE public.credit_card_invoices IS 'Faturas mensais de cartão de crédito (mês de referência, valor, vencimento, pagamento).';
COMMENT ON TABLE public.credit_card_transactions IS 'Transações/lançamentos de cartão de crédito (descrição, valor, parcelas), vinculáveis a fatura e NF.';
COMMENT ON TABLE public.financial_records IS 'Registros financeiros consolidados por grupo/subgrupo de categoria e loja. Fonte da DRE/P&L (receita x despesa).';
COMMENT ON TABLE public.financial_entries IS '(?) Lançamentos financeiros por competência/unidade (unit_slug) e categoria. Tabela aparenta ser legada/pouco usada no app.';
