COMMENT ON TABLE public.financial_account_attachments IS 'Anexos vinculados a uma financial_accounts (arquivo, tipo, tamanho).';
COMMENT ON TABLE public.financial_categories IS 'Categorias financeiras configuráveis (tipo, categoria-pai, ordem de exibição).';
COMMENT ON TABLE public.financial_payroll_entries IS 'Lançamentos de folha de pagamento por loja/mês (salário, horas extras, encargos, líquido).';
COMMENT ON TABLE public.financial_budget_targets IS 'Metas orçamentárias por grupo/subgrupo de categoria, período, cenário e loja (orçado vs realizado).';
COMMENT ON TABLE public.financial_kpi_definitions IS 'Definições de KPIs financeiros (código, fórmula/lógica, formato, meta).';
COMMENT ON TABLE public.financial_forecasts IS 'Previsões financeiras por métrica/data (valor previsto, limites e confiança), por loja.';
COMMENT ON TABLE public.financial_audit_log IS 'Trilha de auditoria das tabelas financeiras (tabela, registro, ação, dados antes/depois, autor).';
COMMENT ON TABLE public.exchange_rates IS 'Taxas de câmbio por data (moeda base/alvo). Auxiliar para conversões financeiras.';

-- financeiro: razão contábil (account_*) e gerencial/tributário (finance_*)
COMMENT ON TABLE public.account_accounts IS 'Plano de contas contábil (código, nome, tipo de conta). Núcleo do razão contábil estilo Odoo.';
COMMENT ON TABLE public.account_journals IS 'Diários contábeis (ex.: vendas, compras, caixa) com conta padrão. Agrupam lançamentos por tipo.';
COMMENT ON TABLE public.account_moves IS 'Lançamentos contábeis (cabeçalho do assento): data, diário, estado, parceiro, valor total, loja.';
COMMENT ON TABLE public.account_move_lines IS 'Linhas de lançamento contábil (débito/crédito por conta), com conciliação, subconta gerencial e centro de custo.';
COMMENT ON TABLE public.account_assets IS 'Ativos imobilizados para depreciação (valor, vida útil, método, estado), por loja.';
COMMENT ON TABLE public.finance_mgmt_groups IS 'Grupos da estrutura financeira gerencial (DRE gerencial) — nível mais alto.';
