COMMENT ON TABLE public.finance_category_mgmt_map IS 'Mapeia categorias de origem (ex.: PDV, contas) para subcontas gerenciais (de->para da classificação financeira).';
COMMENT ON TABLE public.finance_payment_methods IS 'Métodos de pagamento configuráveis usados no razão contábil/lançamentos.';
COMMENT ON TABLE public.finance_document_types IS 'Tipos de documento configuráveis para lançamentos contábeis (ex.: NF, recibo).';
COMMENT ON TABLE public.finance_tax_families IS 'Famílias de tributos (ex.: ICMS, PIS, COFINS, ISS) com escopo de aplicação.';
COMMENT ON TABLE public.finance_tax_rates IS 'Alíquotas por família de tributo, com vigência, UF, regime e flags de recuperável/dedutível.';
COMMENT ON TABLE public.finance_tax_posting_rules IS 'Regras de contabilização por família de tributo (contas de recuperação, a pagar, dedução, despesa).';
COMMENT ON TABLE public.finance_tax_sets IS 'Conjuntos tributários (combinações de famílias/alíquotas) reutilizáveis, por escopo.';
COMMENT ON TABLE public.finance_tax_set_items IS 'Itens de um conjunto tributário (família + alíquota, em sequência).';

-- Degust POS
COMMENT ON TABLE public.degust_stores IS 'Mapeamento entre lojas do POS Degust (franquia/loja) e a loja_id interna do Gidape.';
COMMENT ON TABLE public.degust_product_mapping IS 'Mapeia produtos do Degust (código/nome) para produto_master_id, com multiplicador de quantidade e tipo de match.';
COMMENT ON TABLE public.degust_vendas_diarias IS 'Cache de vendas diárias do Degust por loja/produto (quantidade, valor, nº transações).';

-- funcionários / RH
COMMENT ON TABLE public.cargos IS 'Cargos/funções do RH (área, piso salarial de referência, código CCT). Módulo Funcionários.';
COMMENT ON TABLE public.employees IS 'Cadastro de funcionários (dados pessoais, contratuais, salário, jornada, loja, cargo, status de admissão/desligamento).';
