COMMENT ON TABLE public.metodos_punitivos IS 'Medidas disciplinares (advertências e suspensões) por funcionário, com PDFs gerado/assinado e status.';
COMMENT ON TABLE public.notificacoes_master IS 'Notificações para o master/RH (férias, punitivos, desligamentos pendentes). Consumidas em tempo real pelo sino e banner.';
COMMENT ON TABLE public.lgpd_solicitacoes IS 'Solicitações LGPD de titulares (acesso/correção/exclusão de dados), com prazo e resposta. Vinculadas a funcionário/usuário.';
COMMENT ON TABLE public.pesquisa_saida IS 'Entrevista de desligamento (exit interview): motivo de saída e notas de satisfação por funcionário.';
COMMENT ON TABLE public.pesquisa_clima_ciclos IS 'Ciclos de pesquisa de clima organizacional (período, loja, ativo).';
COMMENT ON TABLE public.pesquisa_clima_respostas IS 'Respostas anônimas (user_hash) a um ciclo de pesquisa de clima, com notas de satisfação.';
COMMENT ON TABLE public.freelancers IS 'Cadastro de freelancers recorrentes (valor da diária, chave PIX, status), por loja.';
COMMENT ON TABLE public.freelancer_work_days IS 'Dias trabalhados por um freelancer cadastrado (data, valor da diária, local/setor), por loja.';
COMMENT ON TABLE public.freelancer_avulso_work_days IS 'Dias trabalhados por freelancer avulso (não cadastrado), informado pelo nome, com valor da diária e local.';

-- usuários, permissões, sistema
COMMENT ON TABLE public.usuarios IS 'Usuários do bot Telegram (legado), identificados por telegram_id. Distinto de profiles/auth.users do app.';
COMMENT ON TABLE public.profiles IS 'Perfil do usuário do app (vinculado a auth.users): nome, role, loja padrão, aprovação e permissões de troca de loja.';
COMMENT ON TABLE public.user_roles IS 'Papéis/roles do sistema (admin, gerente, operação etc.) com nome técnico e permissão de troca de loja.';
COMMENT ON TABLE public.permissions IS 'Permissões granulares por módulo, atribuídas a roles via role_permissions.';
COMMENT ON TABLE public.role_permissions IS 'Tabela de junção entre roles e permissões (quais permissões cada papel possui).';
COMMENT ON TABLE public.user_role_assignments IS 'Atribuição de roles a usuários (modelo multi-role; relaciona auth.users a user_roles).';
COMMENT ON TABLE public.user_admins IS 'Lista de usuários administradores (auth.users marcados como admin do sistema).';
COMMENT ON TABLE public.user_approvals IS 'Registro de aprovação de novos usuários (quem aprovou, quando, notas).';
COMMENT ON TABLE public.user_stores IS 'Vínculo usuário-loja (lojas que o usuário pode acessar; is_default = loja padrão). Modelo multi-loja por usuário.';
COMMENT ON TABLE public.user_preferences IS 'Preferências do usuário (notificações por email/push, tema escuro).';
COMMENT ON TABLE public.subscriptions IS '(?) Assinaturas Stripe (plano, período, status). Provável estrutura de SaaS, ainda não em uso (0 linhas).';
COMMENT ON TABLE public.configuracoes_sistema IS 'Configurações chave-valor do sistema (chave única, valor, tipo, categoria).';
COMMENT ON TABLE public.system_announcements IS 'Comunicados/novidades do sistema exibidos aos usuários (versão, categoria, prioridade, CTA, roles-alvo).';
COMMENT ON TABLE public.user_announcement_reads IS 'Controle de leitura/dispensa de comunicados por usuário (lido, CTA clicado, dispensado).';
COMMENT ON TABLE public.user_activity_log IS 'Log de atividade do usuário no app (tipo de evento, rota, elemento) para analytics de uso.';
